-- Generated from numbered migrations. Do not edit directly.

-- 001_pipeline.sql
CREATE TABLE jobs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company text NOT NULL,
  role text NOT NULL,
  url text,
  url_key text UNIQUE,
  status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending','Evaluated','Applied','Interview','Offer','Rejected','Discarded','SKIP')),
  notes text NOT NULL DEFAULT '',
  score numeric CHECK (score BETWEEN 0 AND 5),
  report_path text,
  jd_path text,
  source_date date,
  created_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  applied_at timestamptz,
  evaluated_at timestamptz,
  revision bigint NOT NULL DEFAULT 0,
  evaluation_error text
);
CREATE INDEX jobs_status_id ON jobs(status,id);
CREATE TABLE evaluations (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES jobs(id),
  operation_key text NOT NULL UNIQUE,
  score numeric CHECK (score BETWEEN 0 AND 5),
  report_path text NOT NULL,
  result_status text NOT NULL CHECK (result_status IN ('Evaluated','SKIP','Discarded')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE job_status_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  job_id bigint NOT NULL REFERENCES jobs(id),
  old_status text,
  new_status text NOT NULL,
  reason text NOT NULL DEFAULT '',
  actor text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX job_status_events_job ON job_status_events(job_id,id);
CREATE TABLE workflow_claims (
  resource text PRIMARY KEY,
  owner_token text NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE TABLE scan_history (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  url text NOT NULL,
  first_seen date,
  portal text NOT NULL DEFAULT '',
  title text NOT NULL DEFAULT '',
  company text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT '',
  location text NOT NULL DEFAULT ''
);
CREATE INDEX scan_history_url ON scan_history(url);
CREATE TABLE legacy_imports (
  fingerprint text PRIMARY KEY,
  imported_at timestamptz NOT NULL DEFAULT now(),
  job_count integer NOT NULL
);
CREATE FUNCTION create_job(p_company text,p_role text,p_url text,p_key text,p_jd text)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs;
BEGIN
  INSERT INTO jobs(company,role,url,url_key,jd_path,created_at)
  VALUES(p_company,p_role,p_url,p_key,p_jd,now())
  ON CONFLICT(url_key) DO NOTHING RETURNING * INTO result;
  IF result.id IS NULL THEN SELECT * INTO result FROM jobs WHERE url_key=p_key; END IF;
  RETURN result;
END $$;
CREATE FUNCTION change_job_status(p_id bigint,p_revision bigint,p_status text,p_reason text,p_actor text)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs; previous text;
BEGIN
  SELECT * INTO result FROM jobs WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Job % does not exist',p_id; END IF;
  IF result.revision<>p_revision THEN RAISE EXCEPTION 'Revision conflict for job %; refresh and retry',p_id USING ERRCODE='40001'; END IF;
  previous:=result.status;
  UPDATE jobs SET status=p_status,revision=revision+1,updated_at=now(),
    applied_at=CASE WHEN p_status='Applied' THEN coalesce(applied_at,now()) ELSE applied_at END,
    notes=CASE WHEN p_reason='' THEN notes ELSE concat_ws(E'\n',nullif(notes,''),p_reason) END
    WHERE id=p_id RETURNING * INTO result;
  INSERT INTO job_status_events(job_id,old_status,new_status,reason,actor) VALUES(p_id,previous,p_status,p_reason,p_actor);
  RETURN result;
END $$;
CREATE FUNCTION claim_work(p_resource text,p_owner text,p_seconds integer)
RETURNS boolean LANGUAGE plpgsql AS $$
BEGIN
  IF p_seconds<1 OR p_seconds>3600 THEN RAISE EXCEPTION 'Invalid lease duration'; END IF;
  INSERT INTO workflow_claims VALUES(p_resource,p_owner,now()+make_interval(secs=>p_seconds))
  ON CONFLICT(resource) DO UPDATE SET owner_token=excluded.owner_token,expires_at=excluded.expires_at
  WHERE workflow_claims.expires_at<now() OR workflow_claims.owner_token=p_owner;
  RETURN FOUND;
END $$;
CREATE FUNCTION complete_evaluation(p_id bigint,p_owner text,p_key text,p_score numeric,p_report text,p_status text,p_note text)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs; previous text; existing evaluations;
BEGIN
  SELECT * INTO result FROM jobs WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown job %',p_id; END IF;
  SELECT * INTO existing FROM evaluations WHERE operation_key=p_key;
  IF FOUND THEN
    IF existing.job_id<>p_id OR existing.report_path<>p_report OR existing.score IS DISTINCT FROM p_score OR existing.result_status<>p_status THEN
      RAISE EXCEPTION 'Conflicting idempotency key';
    END IF;
    RETURN result;
  END IF;
  PERFORM 1 FROM workflow_claims WHERE resource='evaluation:'||p_id AND owner_token=p_owner AND expires_at>now() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evaluation lease lost for %',p_id; END IF;
  INSERT INTO evaluations(job_id,operation_key,score,report_path,result_status) VALUES(p_id,p_key,p_score,p_report,p_status);
  previous:=result.status;
  UPDATE jobs SET score=p_score,report_path=p_report,evaluated_at=now(),updated_at=now(),revision=revision+1,
    status=CASE WHEN status='Pending' THEN p_status ELSE status END,
    notes=concat_ws(E'\n',nullif(notes,''),nullif(p_note,'')),evaluation_error=NULL
    WHERE id=p_id RETURNING * INTO result;
  IF previous<>result.status THEN
    INSERT INTO job_status_events(job_id,old_status,new_status,reason,actor) VALUES(p_id,previous,result.status,p_note,'evaluation');
  END IF;
  RETURN result;
END $$;

-- 002_metadata.sql
CREATE FUNCTION update_job_metadata(p_id bigint,p_revision bigint,p_role text,p_note text)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs;
BEGIN
  SELECT * INTO result FROM jobs WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown job %',p_id; END IF;
  IF result.revision<>p_revision THEN RAISE EXCEPTION 'Revision conflict for job %; refresh and retry',p_id USING ERRCODE='40001'; END IF;
  IF p_role IS NOT NULL AND length(trim(p_role))=0 THEN RAISE EXCEPTION 'Role must not be empty'; END IF;
  UPDATE jobs SET role=coalesce(p_role,role),
    notes=concat_ws(E'\n',nullif(notes,''),nullif(p_note,'')),
    revision=revision+1,updated_at=now() WHERE id=p_id RETURNING * INTO result;
  RETURN result;
END $$;

-- 003_job_descriptions.sql
CREATE TABLE job_descriptions (
  job_id bigint PRIMARY KEY REFERENCES jobs(id),
  content text NOT NULL CHECK (length(btrim(content)) > 0),
  file_path text NOT NULL,
  content_hash text NOT NULL,
  revision bigint NOT NULL DEFAULT 1,
  synced_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION sync_job_description(p_id bigint,p_content text,p_path text,p_hash text)
RETURNS job_descriptions LANGUAGE plpgsql AS $$
DECLARE result job_descriptions;
BEGIN
  PERFORM 1 FROM jobs WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown job %',p_id; END IF;
  INSERT INTO job_descriptions(job_id,content,file_path,content_hash)
  VALUES(p_id,p_content,p_path,p_hash)
  ON CONFLICT(job_id) DO UPDATE SET content=excluded.content,file_path=excluded.file_path,
    content_hash=excluded.content_hash,revision=job_descriptions.revision+1,synced_at=now()
  WHERE job_descriptions.content IS DISTINCT FROM excluded.content
     OR job_descriptions.file_path IS DISTINCT FROM excluded.file_path;
  UPDATE jobs SET jd_path=p_path WHERE id=p_id AND jd_path IS DISTINCT FROM p_path;
  SELECT * INTO result FROM job_descriptions WHERE job_id=p_id;
  RETURN result;
END $$;

-- 004_source_dates.sql
-- Every newly ingested job receives the date it was sourced. Keep the
-- original five-argument function for older callers and imports, which may
-- legitimately have an unknown historical source date.
CREATE FUNCTION create_job(p_company text,p_role text,p_url text,p_key text,p_jd text,p_source_date date)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs;
BEGIN
  INSERT INTO jobs(company,role,url,url_key,jd_path,source_date,created_at)
  VALUES(p_company,p_role,p_url,p_key,p_jd,p_source_date,now())
  ON CONFLICT(url_key) DO NOTHING RETURNING * INTO result;
  IF result.id IS NULL THEN SELECT * INTO result FROM jobs WHERE url_key=p_key; END IF;
  RETURN result;
END $$;

-- The manual-paste JD is the authoritative record of its ingestion date.
-- Backfill only those records; unknown legacy source dates remain null.
UPDATE jobs AS job
SET source_date = (regexp_match(description.content, '(?m)^fetched:\s*(\d{4}-\d{2}-\d{2})\s*$'))[1]::date
FROM job_descriptions AS description
WHERE description.job_id = job.id
  AND job.source_date IS NULL
  AND description.content ~ '(?m)^source:\s*manual-paste\s*$'
  AND description.content ~ '(?m)^fetched:\s*\d{4}-\d{2}-\d{2}\s*$';

-- 005_data_layout.sql
-- 2026-09-19 repository layout change (documentation/guides/layout.md):
-- jds/ moved to data/jds/ and reports/ moved to data/evaluations/.
-- Stored paths are relative to the repository root, so rewrite the prefixes.
UPDATE jobs SET report_path = 'data/evaluations/' || substr(report_path, 9) WHERE report_path LIKE 'reports/%';
UPDATE evaluations SET report_path = 'data/evaluations/' || substr(report_path, 9) WHERE report_path LIKE 'reports/%';
UPDATE jobs SET jd_path = 'data/jds/' || substr(jd_path, 5) WHERE jd_path LIKE 'jds/%';
UPDATE job_descriptions SET file_path = 'data/jds/' || substr(file_path, 5) WHERE file_path LIKE 'jds/%';

-- 006_status_lifecycle.sql
-- Merge the legacy SKIP status into Discarded and add automatic ghosting.
UPDATE jobs SET status = 'Discarded' WHERE status = 'SKIP';
UPDATE evaluations SET result_status = 'Discarded' WHERE result_status = 'SKIP';
UPDATE job_status_events SET old_status = 'Discarded' WHERE old_status = 'SKIP';
UPDATE job_status_events SET new_status = 'Discarded' WHERE new_status = 'SKIP';

ALTER TABLE jobs DROP CONSTRAINT jobs_status_check;
ALTER TABLE jobs ADD CONSTRAINT jobs_status_check
  CHECK (status IN ('Pending','Evaluated','Applied','Interview','Offer','Rejected','Discarded','Ghosted'));

ALTER TABLE evaluations DROP CONSTRAINT evaluations_result_status_check;
ALTER TABLE evaluations ADD CONSTRAINT evaluations_result_status_check
  CHECK (result_status IN ('Evaluated','Discarded'));

-- Preserve the actual application transition date where historical status
-- events can fill a missing applied_at value.
UPDATE jobs AS job
SET applied_at = event.first_applied_at
FROM (
  SELECT job_id, min(created_at) AS first_applied_at
  FROM job_status_events
  WHERE new_status = 'Applied'
  GROUP BY job_id
) AS event
WHERE job.id = event.job_id AND job.applied_at IS NULL;

CREATE OR REPLACE FUNCTION change_job_status(p_id bigint,p_revision bigint,p_status text,p_reason text,p_actor text)
RETURNS jobs LANGUAGE plpgsql AS $$
DECLARE result jobs; previous text;
BEGIN
  SELECT * INTO result FROM jobs WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Job % does not exist',p_id; END IF;
  IF result.revision<>p_revision THEN RAISE EXCEPTION 'Revision conflict for job %; refresh and retry',p_id USING ERRCODE='40001'; END IF;
  IF p_status='Discarded' AND length(btrim(coalesce(p_reason,'')))=0 THEN RAISE EXCEPTION 'Discard reason is required'; END IF;
  previous:=result.status;
  UPDATE jobs SET status=p_status,revision=revision+1,updated_at=now(),
    applied_at=CASE WHEN p_status='Applied' AND previous<>'Applied' THEN now() ELSE applied_at END,
    notes=CASE WHEN p_reason='' THEN notes ELSE concat_ws(E'\n',nullif(notes,''),p_reason) END
    WHERE id=p_id RETURNING * INTO result;
  INSERT INTO job_status_events(job_id,old_status,new_status,reason,actor) VALUES(p_id,previous,p_status,p_reason,p_actor);
  RETURN result;
END $$;

CREATE FUNCTION ghost_stale_applications()
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE moved_count integer;
BEGIN
  WITH moved AS (
    UPDATE jobs
    SET status='Ghosted',revision=revision+1,updated_at=now()
    WHERE status='Applied' AND applied_at < now()-interval '40 days'
    RETURNING id
  )
  INSERT INTO job_status_events(job_id,old_status,new_status,reason,actor)
  SELECT id,'Applied','Ghosted','No response 40 days after application','dashboard-auto'
  FROM moved;
  GET DIAGNOSTICS moved_count = ROW_COUNT;
  RETURN moved_count;
END $$;

-- 007_repair_imported_application_dates.sql
-- Migration 006 initially treated legacy-import status events as application
-- events. Those events record the PostgreSQL cutover time, not the historical
-- application time. Recover only dates explicitly preserved by the old
-- move-status command in notes; leave all other historical dates unknown.
WITH imported_applied AS (
  SELECT job.id,
    (regexp_match(job.notes, '(?i)Applied[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1] AS application_date
  FROM jobs AS job
  WHERE EXISTS (
    SELECT 1
    FROM job_status_events AS event
    WHERE event.job_id=job.id
      AND event.actor='migration'
      AND event.new_status='Applied'
      AND event.created_at=job.applied_at
  )
)
UPDATE jobs AS job
SET applied_at=CASE
      WHEN imported.application_date IS NULL THEN NULL
      ELSE imported.application_date::date::timestamp AT TIME ZONE 'America/Toronto'
    END,
    revision=job.revision+1,
    updated_at=now()
FROM imported_applied AS imported
WHERE job.id=imported.id;

-- 008_status_event_occurrence.sql
-- Distinguish when a transition happened from when its history row was
-- recorded. Legacy rows were inserted during the PostgreSQL cutover, so their
-- created_at values are not evidence of the original transition date.
ALTER TABLE job_status_events ADD COLUMN occurred_at timestamptz;

-- Native PostgreSQL transitions were recorded at the time they happened.
UPDATE job_status_events
SET occurred_at = created_at
WHERE actor <> 'migration';

-- Recover legacy dates only from evidence preserved before the cutover.
-- Application dates were repaired by migration 007. Evaluated dates can be
-- recovered from the dated immutable report path. Other statuses require an
-- explicit status/date note; anything else deliberately remains unknown.
WITH recovered AS (
  SELECT event.id,
    CASE event.new_status
      WHEN 'Applied' THEN job.applied_at::date
      WHEN 'Evaluated' THEN coalesce(
        job.evaluated_at::date,
        ((regexp_match(job.report_path, '([0-9]{4}-[0-9]{2}-[0-9]{2})[.]md$'))[1])::date
      )
      WHEN 'Interview' THEN
        ((regexp_match(job.notes, '(?i)(?:^|[;,.][[:space:]]*)interview(?:ed)?[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1])::date
      WHEN 'Offer' THEN
        ((regexp_match(job.notes, '(?i)(?:^|[;,.][[:space:]]*)offer(?:ed)?[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1])::date
      WHEN 'Rejected' THEN
        ((regexp_match(job.notes, '(?i)(?:^|[;,.][[:space:]]*)rejected[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1])::date
      WHEN 'Ghosted' THEN
        ((regexp_match(job.notes, '(?i)(?:^|[;,.][[:space:]]*)ghosted[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1])::date
      WHEN 'Discarded' THEN
        ((regexp_match(job.notes, '(?i)(?:^|[;,.][[:space:]]*)discarded[[:space:]]+([0-9]{4}-[0-9]{2}-[0-9]{2})'))[1])::date
    END AS status_date
  FROM job_status_events AS event
  JOIN jobs AS job ON job.id=event.job_id
  WHERE event.actor='migration' AND event.new_status=job.status
)
UPDATE job_status_events AS event
SET occurred_at = recovered.status_date::timestamp AT TIME ZONE 'America/Toronto'
FROM recovered
WHERE event.id=recovered.id AND recovered.status_date IS NOT NULL;

ALTER TABLE job_status_events ALTER COLUMN occurred_at SET DEFAULT now();

-- 009_salary_band.sql
ALTER TABLE jobs ADD COLUMN salary_min numeric;
ALTER TABLE jobs ADD COLUMN salary_max numeric;
ALTER TABLE jobs ADD CONSTRAINT jobs_salary_band_check CHECK (
  salary_min IS NULL OR salary_max IS NULL OR (salary_min >= 0 AND salary_max >= salary_min)
);
